CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_key text NOT NULL UNIQUE, readonly boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text NOT NULL UNIQUE, role_key text NOT NULL REFERENCES roles(role_key));
CREATE TABLE IF NOT EXISTS leave_requests (id text PRIMARY KEY, employee_id text NOT NULL, manager_id text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, business_days integer NOT NULL CHECK (business_days > 0), reason text NOT NULL, balance_days integer NOT NULL, stage text NOT NULL, revision integer NOT NULL DEFAULT 0, operation_key text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS leave_transitions (id bigserial PRIMARY KEY, leave_id text NOT NULL REFERENCES leave_requests(id), sequence integer NOT NULL, operation_key text NOT NULL UNIQUE, action text NOT NULL, actor_id text NOT NULL, from_stage text NOT NULL, to_stage text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (leave_id, sequence));
CREATE TABLE IF NOT EXISTS flow_tasks (id text PRIMARY KEY, flow_id text NOT NULL, subject_id text NOT NULL, stage text NOT NULL, role_key text NOT NULL, status text NOT NULL, assignee_id text, revision integer NOT NULL DEFAULT 0, lifecycle_epoch integer NOT NULL DEFAULT 0, due_at timestamptz, opened_operation_key text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS flow_task_events (id bigserial PRIMARY KEY, task_id text NOT NULL REFERENCES flow_tasks(id), sequence integer NOT NULL, operation_key text NOT NULL, event_type text NOT NULL, actor_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (task_id, sequence));
CREATE TABLE IF NOT EXISTS notification_outbox (id text PRIMARY KEY, dedupe_key text NOT NULL UNIQUE, channel text NOT NULL, status text NOT NULL, attempt_count integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS notification_inbox (id text PRIMARY KEY, user_id text NOT NULL, dedupe_key text NOT NULL UNIQUE, subject text NOT NULL, body text NOT NULL, read_at timestamptz);
CREATE TABLE IF NOT EXISTS audit_events (id bigserial PRIMARY KEY, actor_id text NOT NULL, action text NOT NULL, entity_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS demo_runtime_state (state_key text PRIMARY KEY, state_value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
